function renderPanel(sub){$('echoSuggestions').hidden=state.view!=='echo'||!terminalOn()||!!state.ending||!!state.exit;const title={map:'지도',bag:'소지품과 몸 상태',book:'사건수첩',echo:hasFlag('operatorProof')?'ECHO · 윤서':'ECHO · 메시지',settings:'설정'};$('panelTitle').textContent=title[state.view]||'';$('panelClose').textContent=state.view==='echo'?'단말기 닫기':'현장으로 돌아가기';if(state.view==='map')renderMap();else if(state.view==='bag')renderBag(sub);else if(state.view==='book')renderBook(sub);else if(state.view==='echo')renderEcho();else if(state.view==='settings')renderSettings();}
function renderMap(){const blocked=state.event?'현재 위기를 해결한 뒤 이동할 수 있습니다.':state.exit||state.ending?'마을 밖으로 나와 이동이 종료됐습니다.':state.loc==='ward'&&!hasFlag('firstSave')?'점검문으로 안전하게 나갈 방법을 먼저 확인하세요.':'';const lines=[];for(const [id,w] of Object.entries(WORLD))for(const d of w.links)if(id<d)lines.push('<line x1="'+w.x+'" y1="'+w.y+'" x2="'+WORLD[d].x+'" y2="'+WORLD[d].y+'"/>');$('panelScroll').innerHTML=(blocked?'<div class="notice danger">'+blocked+'</div>':'')+(state.reportFocus?'<div class="locationReport">ECHO 제보: '+WORLD[state.reportFocus].name+' · 확인된 현재 위치가 아닙니다.</div>':'')+'<p class="mapKey">밝은 테두리: 바로 이동 가능 · 경로선을 따라 한 장소씩 이동<br>현재 위치: '+WORLD[state.loc].name+' · 목적: '+escapeHTML(objective())+'</p><div class="mapSurface"><svg viewBox="0 0 100 100" preserveAspectRatio="none">'+lines.join('')+'</svg>'+Object.entries(WORLD).map(([id,w])=>{const known=true,here=id===state.loc,available=known&&WORLD[state.loc].links.includes(id)&&!blocked;return'<button class="mapNode '+(here?'here':available?'available':'')+(state.reportFocus===id?' reported':'')+'" style="left:'+w.x+'%;top:'+w.y+'%" data-place="'+id+'" '+(!available?'disabled':'')+' aria-label="'+w.name+' '+(here?'현재 위치':available?'이동 가능':known?'인접 장소를 경유해야 함':'위치 미확인')+'">'+(known?w.name:'?')+(here?'<br>현재 위치':'')+'</button>'}).join('')+'</div><div class="entry"><h3>지금 이동할 수 있는 곳</h3>'+WORLD[state.loc].links.map(id=>'<button data-place="'+id+'" '+(blocked?'disabled':'')+'>'+WORLD[id].name+(state.visited.includes(id)?' →':' · 처음 탐색')+'</button>').join(' ')+'</div>';$('panelScroll').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>move(b.dataset.place));}
function renderBag(sub){if(sub==='treatment')bagTab='body';const items=Object.entries(state.items).filter(([k,n])=>n>0);let body='<div class="tabs"><button data-bag="items" class="'+(bagTab==='items'?'active':'')+'">물품</button><button data-bag="body" class="'+(bagTab==='body'?'active':'')+'">몸·치료</button></div>';if(bagTab==='items'){body+='<div class="grid">'+items.map(([k,n])=>'<button class="item" data-item="'+k+'">'+imageTag('assets/items/'+ITEMS[k].icon+'.svg','')+'<span>'+ITEMS[k].name+' × '+n+'<small>'+escapeHTML(ITEMS[k].desc)+'</small></span></button>').join('')+'</div>'+(!items.length?'<p>지닌 물품이 없습니다.</p>':'')+'<p class="small">증거와 기록은 사건수첩에 모입니다. 구급상자를 누르면 치료할 부위를 선택합니다.</p>';}else{body+='<div class="bodySheet">'+imageTag(playerPortrait(),'현재 주인공의 몸 상태')+'<div><h3>'+(hasClue('identity')?'이현':'이름 미상 · 0417')+'</h3><p>체력 '+state.hp+'/100<br>침식 '+state.erosion+'%<br>'+(state.injuries.map(p=>PARTS[p]+' 부상').join('<br>')||'확인한 신체 부상 없음')+'</p><p class="small">몸의 부상은 구급상자로 치료합니다. 침식은 단말기 사용을 쉬고 안전한 곳에서 안정을 취해 줄일 수 있습니다. 단말기만 껐다고 이미 쌓인 침식이 즉시 사라지지는 않습니다.</p></div></div><div class="entry"><h3>구급상자 '+(state.items.med||0)+'개</h3><p>한 부위를 치료합니다. 그 부상의 화면 효과와 행동 제한도 함께 사라집니다.</p><div class="actions">'+(state.injuries.some(p=>['eyes','head'].includes(p))?'<button data-treat="vision" '+(!hasItem('med')||state.event?'disabled':'')+'>머리·눈 치료 · 흐림과 글자 손상 제거</button>':'')+state.injuries.filter(p=>!['eyes','head'].includes(p)).map(p=>'<button data-treat="'+p+'" '+(!hasItem('med')||state.event?'disabled':'')+'>'+PARTS[p]+' 치료 · 해당 행동 복구</button>').join('')+'<button data-treat="hp" '+(!hasItem('med')||state.hp===100||state.event?'disabled':'')+'>체력 35 회복 · 부상은 남음</button></div></div>'+state.party.map(n=>'<div class="entry">'+imageTag(npcPortrait(n),n,'portrait')+'<h3>'+n+'</h3><p>'+PEOPLE[n].device+'<br>'+(perceptionBand()==='clouded'?'지금은 눈에 띄는 차이를 찾지 못했다. 높은 침식 상태의 관찰이다.':state.npc[n].changed?'입술보다 단말기의 말이 먼저 들린다.':state.npc[n].sync>=55?'손목과 말투에서 이상 징후가 보인다.':'확인할 새로운 행동을 살펴보자.')+'</p></div>').join('');}
 $('panelScroll').innerHTML=body;$('panelScroll').querySelectorAll('[data-bag]').forEach(b=>b.onclick=()=>{bagTab=b.dataset.bag;renderBag()});$('panelScroll').querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const k=b.dataset.item;if(state.event||state.exit||state.ending)return toast('현재 사건에서는 장면의 대응 선택을 사용하세요.');if(['med','food','filter'].includes(k))useItem(k);else toast(ITEMS[k].desc)});$('panelScroll').querySelectorAll('[data-treat]').forEach(b=>b.onclick=()=>treat(b.dataset.treat));}
function renderBook(sub){if(PEOPLE[sub])bookTab='people';const tabs={summary:'사건 흐름',evidence:'증거·의문',people:'인물',routes:'탈출 준비',endings:'엔딩·진상'};let html='<div class="tabs">'+Object.entries(tabs).map(([id,n])=>'<button data-book="'+id+'" class="'+(bookTab===id?'active':'')+'">'+n+'</button>').join('')+'</div>';if(bookTab==='summary'){const summaries=[];if(hasClue('wrist'))summaries.push('이름을 기억하지 못한 채 0417 손목표를 달고 대피소에서 깨어났다.');if(hasFlag('firstSave'))summaries.push('단말기 너머의 목소리가 실제로 나를 구했다. 그렇다고 다음 말까지 맞는 것은 아니다.');if(hasClue('treatment'))summaries.push('회관에서 다쳐 약국으로 옮겨졌다는 기록을 찾았다.');if(hasClue('job'))summaries.push('이름이 번진 통신 점검 작업일지에서 내 글씨와 닮은 서명을 찾았다.');if(hasClue('schoolTrail'))summaries.push('학교 기록에는 해원이 관리소로 약을 전하러 갔다고 적혀 있다. 실제 도착 여부는 현장에서 확인해야 한다.');if(hasClue('identity'))summaries.push('사진과 원본 카드가 맞아떨어져 내 이름과 방문 목적을 확인했다.');if(hasFlag('operatorProof'))summaries.push('윤서는 실제 응답자였지만 신호 출력을 높인 사실을 숨겼다. 다른 목소리가 연결에 끼어들었다.');html+='<div class="objective">'+escapeHTML(objective())+'</div>'+summaries.map(s=>'<div class="entry">'+s+'</div>').join('')+'<details><summary>지난 현장 대화</summary>'+state.transcript.filter(l=>!terminalLine(l)&&!['thought','narration'].includes(l.kind)).slice(-80).map(l=>'<p class="small"><b>'+escapeHTML(l.speaker||l.who)+'</b> · '+escapeHTML(l.text)+'</p>').join('')+'</details>';}else if(bookTab==='evidence'){html+=state.clues.map(k=>'<div class="entry"><small>'+CLUES[k].kind+' · '+(CLUES[k].digital?'단말기 저장':'실물·현장 확인')+'</small><h3>'+CLUES[k].title+'</h3><p>'+CLUES[k].text+'</p>'+(CLUES[k].question&&!alreadyAsked(CLUES[k].question)?'<button data-question="'+escapeHTML(CLUES[k].question)+'">이 의문을 ECHO에게 묻기</button>':'')+'</div>').join('')+state.claims.map(publicClaim).map(c=>'<div class="entry"><small>'+c.kind+'</small><h3>'+escapeHTML(c.title)+'</h3><p>'+escapeHTML(c.text)+'</p></div>').join('')+'<div class="entry"><h3>아직 확인할 의문</h3><p>'+(!hasClue('identity')?(hasClue('job')?'작업일지의 서명은 내가 쓴 것일까?<br>':'손목의 번호는 누구에게, 왜 받은 걸까?<br>'):'')+(!hasFlag('operatorProof')?'단말기 너머의 사람은 누구이며 무엇을 숨기는가?<br>':'')+'내가 보는 모습과 다른 사람의 행동이 같은 사실을 가리키는가?</p></div>';}
 else if(bookTab==='people'){html+=identityRules();html+='<p class="small">직접 만난 사람 '+state.met.length+'명 + 주인공 1명. 얼굴만으로 정체를 판정하지 않습니다.</p>'+state.met.map(n=>{const c=state.npc[n],here=c.location===state.loc;return'<div class="entry">'+imageTag(npcPortrait(n),n,'portrait')+'<h3>'+n+' · '+({available:'동행 결정 전',party:'동행 중',away:'따로 이동',dead:'사망',care:'구조팀과 대기',released:'외부 대피소로 이동'}[c.status]||'상태 불명')+'</h3>'+personEvidence(n)+'<p>'+PEOPLE[n].goal+'<br>'+PEOPLE[n].device+'<br>마지막 확인 장소: '+WORLD[c.location].name+'</p>'+(here&&!['dead','care'].includes(c.status)&&!state.event&&!state.exit&&!state.ending?'<div class="actions"><button data-inspect="'+n+'" data-mode="memory" '+(inspectionLocked(n,'memory')?'disabled':'')+'>처음 나눈 말과 기억을 묻는다</button><button data-inspect="'+n+'" data-mode="object" '+(inspectionLocked(n,'object')?'disabled':'')+'>처음 기록한 물건과 비교한다</button><button data-inspect="'+n+'" data-mode="trace" '+(inspectionLocked(n,'trace')?'disabled':'')+'>움직임과 흔적을 관찰한다</button>'+['filter','med','food'].filter(hasItem).map(k=>'<button data-support="'+n+'" data-supply="'+k+'">'+ITEMS[k].name+'로 돕기 · 1개 사용</button>').join('')+''+(state.party.includes(n)?'<button data-leave="'+n+'">각자 다른 곳을 확인하기로 한다</button>':'<button data-join="'+n+'">동행 요청 · 이전 행동에 따라 거절 가능</button>')+'</div>':'')+'</div>'}).join('');}
 else if(bookTab==='routes'){for(const [route,label] of Object.entries({sea:'부두의 배',school:'학교 비상문',drain:'저류조 점검 통로',rail:'폐역 점검차',light:'등대 구조 신호',forest:'숲 외부 점검길',operator:'윤서의 정비 터널'}))html+='<div class="entry"><h3>'+label+'</h3><p>'+escapeHTML(escapeReason(route)||'준비 완료 · 해당 장소에서 실행')+'</p></div>';}
 else {html+='<p>발견한 엔딩 '+meta.ends.length+' / '+ENDS.length+'</p>'+ENDS.map(e=>'<div class="entry"><h3>'+String(e.n).padStart(2,'0')+' · '+(meta.ends.includes(e.id)?e.title:'아직 확인하지 않은 결말')+'</h3>'+(meta.ends.includes(e.id)?endingArtwork(e.id,meta.endingCards?.[e.id],true)+'<p>'+escapeHTML(e.text)+'</p>':'')+'</div>').join('');if(canReadTruth()){html+='<details class="entry"><summary>주요 사건의 진상 · 스포일러</summary>'+TRUTH.filter(([t])=>t!=='차단을 미룬 이유'||meta.knowledge.includes('delay')).slice(0,7).map(([t,s])=>'<h3>'+t+'</h3><p>'+s+'</p>').join('')+'</details>';}else html+='<div class="entry">작업일지·원본 카드·원본 녹음·숨겨진 보고서를 모으면 주요 사건의 진상이 열립니다.</div>';if(meta.truthUnlocked||ENDS.every(e=>meta.ends.includes(e.id)))html+='<details class="entry"><summary>모든 결말 뒤의 전체 진상</summary>'+TRUTH.map(([t,s])=>'<h3>'+t+'</h3><p>'+s+'</p>').join('')+'</details>';else html+='<p class="small">모든 엔딩을 확인하면 각 인물의 행적과 회차의 의미까지 연결한 전체 진상이 열립니다.</p>';}
 $('panelScroll').innerHTML=html.replace(/<button data-inspect=[^>]*\bdisabled[^>]*>[\s\S]*?<\/button>/g,'');$('panelScroll').querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{bookTab=b.dataset.book;renderBook();$('panelScroll').scrollTop=0});bindQuestions();for(const [attr,fn] of Object.entries({inspect:inspectNPC,support:supportNPC,leave:leave,join:join}))$('panelScroll').querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>fn(b.dataset[attr],b.dataset.supply||b.dataset.mode));}
function suggestedQuestions(){const available=state.questions.filter(k=>CLUES[k]?.question),local={clinic:['treatment','wrist'],ward:['wrist'],hall:['job','group','photo'],school:['rules','schoolTrail','group'],pier:['tide'],lighthouse:['tide'],relay:['original','delay','job','photo'],forest:['schoolTrail','group'],station:['footprint']};const keys=[...new Set([...(local[state.loc]||[]).filter(k=>available.includes(k)),...available])];const q=keys.map(k=>CLUES[k].question);if(knownThreat())q.push('그 형체는 지금 어디에 있어?');if(knownPeople())q.push('다른 사람의 위치 제보가 있어?');if(state.injuries.length)q.unshift('어느 부상을 먼저 치료해야 해?');if(state.event)q.unshift(eventQuestion());if(!q.length)q.push('당신은 누구예요?','복도에서 나는 소리는 뭐예요?','내 번호 0417은 무엇을 뜻해?');return [...new Set(q)].filter(q=>!alreadyAsked(q)).slice(0,4);}

function prefill(q){if(!alreadyAsked(q))return ask(q);return false;}
function bindQuestions(){[...$('panelScroll').querySelectorAll('[data-question]'),...$('echoSuggestions').querySelectorAll('[data-question]')].forEach(b=>b.onclick=()=>{if(!terminalOn())return toast('단말기가 꺼져 있습니다.');const q=b.dataset.question;if(alreadyAsked(q))return;openView('echo');ask(q);});}
function renderEcho(){if(!terminalOn()){$('echoSuggestions').innerHTML='';$('panelScroll').innerHTML='<div class="entry"><h3>연결을 끊었습니다</h3><p>'+(hasFlag('discarded')?'단말기를 버려 수신 기록도 사라졌다.':'단말기는 꺼져 있다. 받은 메시지는 남아 있다.')+'</p><button id="echoSettings">단말기 설정</button></div>';$('echoSettings').onclick=()=>openView('settings');return;}const unread=state.mail.splice(0);if(unread.length){for(const m of unread){if(m.type==='survivorLead')flag('survivorLeadRead');state.chat.push({q:'수신 메시지',a:m.text,probability:null,id:'incoming',verified:false});}$('mailBadge').hidden=true;$('echoNav').classList.remove('unread');save();}const frame=terminalFxFrame();const questions=suggestedQuestions();$('echoSuggestions').innerHTML=questions.map((q,i)=>terminalQuestionButton(q,i)).join('')||'<p class="small">새로 물을 내용이 없다. 받은 답변은 수신 기록에 남아 있다.</p>';let html='<div class="channelStatus"><span>'+(hasFlag('operatorProof')?'윤서 · 연결 중':'ECHO · 음성 연결 / 수신 자막')+'</span><span id="questionCostPreview">질문 시 침식 +'+questionCostRange().min+'~'+questionCostRange().max+'</span></div>';html+=terminalAtmosphere(frame)+state.chat.map((m,i)=>terminalMessageHTML(m,frame.fresh&&i===state.chat.length-1)).join('');if(!state.chat.length)html+='<div class="entry">아직 수신 기록이 없습니다.</div>';$('panelScroll').innerHTML=html;if(unread.length)viewScroll.echo=$('panelScroll').scrollHeight;bindQuestions();$('panelScroll').querySelectorAll('[data-report-loc]').forEach(b=>b.onclick=()=>{state.reportFocus=b.dataset.reportLoc;openView('map');});}
function renderSettings(){const p=meta.preferences;$('panelScroll').innerHTML='<div class="setting"><span>화면 흔들림·침식 효과 줄이기</span><button id="reduce">'+(p.reduce?'켜짐':'꺼짐')+'</button></div><div class="setting"><span>글자 크게 보기</span><button id="large">'+(p.large?'켜짐':'꺼짐')+'</button></div><div class="setting"><span>배경음악·이동·충격음</span><button id="sound">'+(p.sound?'켜짐':'꺼짐')+'</button></div><div class="entry"><h3>단말기</h3><p>꺼두면 질문과 원격 안내가 중단되며 메시지는 남습니다. 버리면 메시지와 디지털 기록이 사라집니다. 실물 증거와 물품은 남습니다.</p><button id="terminalToggle" '+(hasFlag('discarded')?'disabled':'')+'>'+(!terminalOn()?'다시 켜기':'단말기 끄기')+'</button> <button id="discard" '+(hasFlag('discarded')?'disabled':'')+'>단말기 버리기</button><div id="discardConfirm" hidden><p>메시지와 디지털 기록을 되찾을 수 없습니다.</p><button id="discardYes">확인하고 버리기</button></div></div><p class="small buildVersion">버전 v5.22</p><div class="entry"><button id="introReplay">처음 안내 다시 보기</button> <button id="exportSave">진행 저장 파일 받기</button><label class="small">저장 파일 불러오기 <input id="importSave" type="file" accept="application/json,.json"></label></div><div class="entry"><button id="newRun">새로운 선택 시작</button><p class="small">현재 진행을 끝내고 새 회차를 시작합니다. 발견한 엔딩과 단서 지식은 남습니다.</p><div id="newConfirm" hidden><button id="newYes">현재 진행을 내려놓고 시작</button></div></div>';$('reduce').onclick=()=>{p.reduce=!p.reduce;render();renderSettings();save()};$('large').onclick=()=>{p.large=!p.large;render();renderSettings();save()};$('sound').onclick=toggleSound;$('terminalToggle').onclick=()=>setTerminal(terminalOn()?'off':'on');$('discard').onclick=()=>{$('discardConfirm').hidden=false};$('discardYes').onclick=()=>setTerminal('discard');$('introReplay').onclick=()=>{introStep=0;showIntro(true)};$('newRun').onclick=()=>{$('newConfirm').hidden=false};$('newYes').onclick=restart;$('exportSave').onclick=()=>{const blob=new Blob([JSON.stringify({version:5,meta,state})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='glass-bay-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('importSave').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const data=JSON.parse(await f.text());if(data.version!==5||!WORLD[data.state?.loc]||!Array.isArray(data.meta?.ends)||!Array.isArray(data.state?.party)||!data.state.npc||Object.keys(PEOPLE).some(n=>!data.state.npc[n]))throw Error();meta=data.meta;state=data.state;openView('scene');render();save();toast('진행을 불러왔습니다.')}catch{toast('이 버전의 올바른 저장 파일이 아닙니다.')}};}
function renderEnding(){const e=ENDS.find(e=>e.id===state.ending);$('sceneView').innerHTML='<div class="sceneArt">'+imageTag(artURL(state.exit?'pier':WORLD[state.loc].art),'마지막 장면')+(state.ending==='assault'&&state.lastAttacker?'<div class="portraits">'+imageTag(npcPortrait(state.lastAttacker),'마지막에 공격한 동행자')+'</div>':state.lastMonsterEnding===state.ending?'<div class="monsterStage fatal">'+imageTag('assets/monsters/'+state.lastMonster+'.png','마지막에 마주한 괴물','monsterSprite')+'</div>':'')+'<div class="sceneTitle"><small>ENDING '+e.n+' / '+ENDS.length+'</small><h1>'+e.title+'</h1></div></div><div class="sceneBody"><h2 class="endingTitle">'+e.title+'</h2><p>'+e.text+'</p><div class="entry"><h3>이번 선택이 남긴 것</h3><p>'+endingEvidence()+'</p></div><div class="entry"><h3>다음 선택에서 확인할 것</h3><p>'+nextLead()+'</p></div><button id="restart" class="primary">다른 선택으로 다시 시작</button> <button id="endingBook">엔딩과 사건수첩</button></div>';$('restart').onclick=restart;$('endingBook').onclick=()=>{bookTab='endings';openView('book')};}
function endingEvidence(){const causes={schoolTaken:'방송이 켜지는 순간 손이 움직이는 것을 보고도, 손이 막은 길로 다시 뛰었다.',forestTaken:'발자국 없는 목소리에 다가갔고, 가로막힌 길을 다시 밀어붙였다.',marketTaken:'시선을 돌릴 때 손이 다가오는 것을 보고도 좁은 천막 안으로 등을 보였다.',waterTaken:'손이 닿는 낮은 발판으로 뛰어내렸고, 붙잡힌 뒤에도 같은 길을 택했다.',reef:'붉은 불빛을 향해 출항한 뒤, 암초에 가까워졌을 때도 계속 진행했다.',name:'본명을 따라 부르는 문 안으로 들어갔다.',drowned:'차오르는 물을 보고도 낮은 통로로 계속 내려갔다.',signal:'완전 침식의 마지막 경고에서 연결을 유지했다.',assault:'공격하는 동행자를 믿고 따라가는 선택을 했다.',caught:'복도의 접근 징후를 확인하지 않고 달리다가 붙잡혔다.',exhausted:'버틸 수 있는 처치나 부축 대신 움직임을 멈췄다.'};const bits=causes[state.ending]?[causes[state.ending]]:[];if(state.exit)bits.push('사용한 출구: '+state.exit.route);if(hasClue('identity'))bits.push('사진·작업일지·원본 카드로 이현의 신원을 확인했다.');if(state.ending==='earned')bits.push('받은 안내와 별개로 현장 설비를 살핀 뒤 길을 골랐다.');if(state.party.some(n=>state.npc[n].fake))bits.push('재회 때 공유한 기억과 흔적이 맞지 않았지만 함께 나왔다.');if(state.party.some(n=>state.npc[n].changed))bits.push('동료의 목소리와 손목 변화가 탈출 전부터 나타났다.');if(state.perception)bits.push('사진·반사와 자신의 시야가 달랐지만 끝까지 확인하지 않았다.');if(hasClue('delay'))bits.push('구조를 위해 차단을 미룬 자신의 결정과 피해가 커진 결과를 함께 확인했다.');if(state.exit?.quarantined?.length)bits.push('따로 확인하도록 구조팀에 맡긴 동행자: '+state.exit.quarantined.join(' · '));if(state.exit?.mistrusted?.length)bits.push('행동이 일치했던 동료도 따로 확인하도록 맡겨 관계가 멀어졌다.');if(!bits.length)bits.push('판단의 근거를 충분히 확보하기 전에 마지막 선택을 했다.');return bits.join('<br>');}
function nextLead(){const monster=Object.values(MONSTERS).find(m=>m.ending===state.ending);if(monster)return monster.tell+' 붙잡힌 뒤에는 물건을 놓거나 동료의 도움으로 빠져나갈 수 있지만 대가가 남는다.';if(state.ending==='reef')return'부두 수위표와 등대의 점멸 간격을 비교하면 어느 불빛이 외항인지 판단할 수 있다. 같은 항로를 다시 택할 필요는 없다.';if(state.ending==='drowned')return'낮은 밸브와 전원을 확인하면 물이 빠진 통로가 열린다. 다른 출구를 준비할 수도 있다.';if(state.ending==='signal')return'신호를 오래 유지한 대가였다. 다음에는 필터나 연결 중단, 원본 회선 확보를 준비할 수 있다.';if(!meta.knowledge.includes('schoolTrail'))return'학교의 노란 봉투를 확인하면 해원이 어디로 갔는지 알 수 있다.';if(!meta.knowledge.includes('identity'))return'회관의 사진과 작업일지를 중계실 카드에 맞춰 보자.';if(!meta.knowledge.includes('archiveLog'))return'다음 접속에는 회관의 잠긴 보고서 서랍과 나래의 지난 방송을 확인할 수 있다.';if(!meta.knowledge.includes('original'))return'중계실의 잘리지 않은 녹음을 찾아 응답자의 설명과 비교하자.';if(!meta.knowledge.includes('delay'))return'세 번째 선택에서는 중계실의 봉인된 작업대에서 네가 마지막에 내린 결정까지 확인할 수 있다.';return'알게 된 진실을 다른 선택에 적용해 보자. 모든 결말은 같은 사건의 다른 결과다.';}
const INTRO_PAGES=[['이름이 비어 있는 아침','눈을 뜨면 손목에 0417이 묶여 있습니다. 자신이 누구인지, 왜 이 마을에 있는지 기억나지 않습니다. 단말기 너머의 누군가가 나갈 길을 알려 줍니다.'],['현장과 지도','장면에서는 조사·대화·행동을 선택합니다. 다른 장소로 갈 때는 하단 지도를 여세요. 연결된 장소로 한 곳씩 이동합니다. 완료한 조사는 사라지고, 조건이 부족한 행동에는 이유가 표시됩니다.'],['질문과 증거','단서를 찾으면 물어볼 의문이 생깁니다. ECHO에서 질문을 선택해 보내거나 직접 입력할 수 있습니다. 답변은 거짓일 수 있고 사용하면 침식이 쌓입니다. 수첩은 사실과 주장을 구분합니다.'],['괴물과 닫힌 길','괴물의 손에 가려진 선택은 실제로 사용할 수 없습니다. 움직임을 살피면 다른 대응을 찾을 수 있습니다. 붙잡혀도 물건을 포기하거나 동료의 도움으로 빠져나갈 기회가 있지만, 막힌 길을 다시 택하면 사망할 수 있습니다. 높은 침식은 화면과 선택에도 영향을 줍니다.'],['몸과 사람','부상은 소지품의 몸·치료에서 부위를 골라 치료합니다. 침식은 부상과 다릅니다. 동료도 단말기를 가지고 있으며 얼굴만으로 정체를 알 수 없습니다. 기억·물건·행동을 대조하세요.']];
function showIntro(force=false){let seen=false;try{seen=localStorage.getItem(INTRO)==='seen'}catch{}if(!force&&seen){$('intro').hidden=true;return}$('intro').hidden=false;$('introTitle').textContent=INTRO_PAGES[introStep][0];$('introText').textContent=INTRO_PAGES[introStep][1];$('introPage').textContent=(introStep+1)+' / '+INTRO_PAGES.length;$('introNext').textContent=introStep===INTRO_PAGES.length-1?'깨어나기':'다음';$('introNext').onclick=()=>{if(introStep<INTRO_PAGES.length-1){introStep++;showIntro(true)}else{$('intro').hidden=true;try{localStorage.setItem(INTRO,'seen')}catch{}}};}
$('panelClose').onclick=()=>openView('scene');$('titleButton').onclick=$('settingsButton').onclick=()=>openView('settings');document.querySelectorAll('#bottomNav button').forEach(b=>b.onclick=()=>openView(b.dataset.view));
document.addEventListener('visibilitychange',()=>{if(document.hidden)music?.pause();else if(meta.preferences.sound)music?.play().catch(()=>{})});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('intro').hidden)openView('scene')});
render();openView(state.view||'scene');
if(window.visualViewport){const syncViewport=()=>{document.documentElement.style.setProperty('--screenH',window.visualViewport.height+'px');document.documentElement.style.setProperty('--screenTop',window.visualViewport.offsetTop+'px')};window.visualViewport.addEventListener('resize',syncViewport);window.visualViewport.addEventListener('scroll',syncViewport);syncViewport();}



function comparisonCard(m){if(m.report){const r=m.report;return '<section class="locationReport"><b>받은 위치 제보</b><p>'+escapeHTML(r.loc?WORLD[r.loc].name:'새 제보 없음')+' · 행동 '+r.asOf+' 때의 수신</p><small>지금 그곳에 있는지는 아직 보지 못했다.</small>'+(r.loc?'<button data-report-loc="'+r.loc+'">제보 위치를 지도에 표시</button>':'')+'</section>';}if(!m.proof||!hasClue(m.proof)||!CLUES[m.proof])return '';const source=CLUES[m.proof];return '<details class="sourceExcerpt"><summary>지닌 기록 펼치기 · '+escapeHTML(source.title)+'</summary><p>'+emphasizeEvidence(source.text)+'</p></details>';}
function personEvidence(n){const c=state.npc[n],o=c.observations||{},differences=Object.values(o).filter(x=>x.bad).length;let html='<div class="personReference"><h4>소지품 · 첫 만남 기록</h4><p>'+escapeHTML(c.baseline?.object||'이전 저장에는 세부 특징 기록이 없습니다. 현재 대화와 움직임을 확인할 수 있습니다.')+'</p>'+(differences?'<span class="discrepancyTag">관찰한 차이 '+differences+'개 · 정체 확인 필요</span>':'')+Object.entries(o).map(([mode,x])=>'<details><summary>'+({memory:'대화',object:'물건',trace:'움직임'}[mode])+' · '+escapeHTML(x.result||(x.bad?'첫 기록과 차이 있음':'관찰 기록 있음'))+'</summary><p>'+escapeHTML(x.text).replace(/\n/g,'<br>')+'</p></details>').join('');const history=(meta.npcHistory?.[n]||[]).filter(h=>h.cycle!==meta.cycle);if(history.length)html+='<details><summary>이전 회차와 별도 대조</summary><p class="small">이전 선택의 기록입니다. 이번에 만난 사람의 정체를 확정하는 근거는 아닙니다.</p>'+history.map(h=>'<p>'+h.cycle+'회차 · '+escapeHTML(h.object)+'<br>이번 회차: '+escapeHTML(c.baseline?.object||'미기록')+'<br>'+((h.object===c.baseline?.object)?'회차 간 물건 특징이 같음':'회차 간 물건 특징이 달라짐')+' · 이번 회차의 재회 판정과는 별도</p>').join('')+'</details>';return html+'</div>';}


// v5.8: short procedural vocal textures; no microphone or remote service.
let vocalAudio=null,vocalLast=-Infinity,vocalPriority=0,breathLast=-Infinity;
function playVocal(kind,priority=1){if(!meta.preferences.sound||meta.preferences.vocals===false||document.hidden)return false;const now=Date.now();if(now-vocalLast<4500&&priority<=vocalPriority)return false;try{vocalAudio?.pause();vocalAudio=new Audio('assets/audio/'+({breath:'breath',gasp:'gasp',cry:'cry'}[kind]||'breath')+'.wav');vocalAudio.volume=kind==='cry'?.23:.32;vocalPriority=priority;vocalLast=now;music&&(music.volume=.09);vocalAudio.onended=()=>{vocalPriority=0;if(music)music.volume=.18;};vocalAudio.play().catch(()=>{vocalPriority=0;if(music)music.volume=.18;});return true;}catch{return false;}}
function stopVocal(){vocalAudio?.pause();vocalAudio=null;vocalPriority=0;if(music)music.volume=.18;}
const beforeDetailSound=soundFX;
soundFX=function(type){beforeDetailSound(type);if(type==='hit')playVocal('gasp',2);if(type==='steps'&&(state.hp<=35||state.event?.stage===3)&&Date.now()-breathLast>9000){breathLast=Date.now();playVocal('breath',1);}if(type==='threat')playVocal('breath',1);};
const beforeDetailResolve=resolveEvent;
resolveEvent=function(id){const e=state.event,wasCaught=e?.stage===3,turn=state.turn;beforeDetailResolve(id);if(state.turn===turn||id==='echo')return;if(!wasCaught&&state.event?.stage===3){playVocal('cry',3);shortEffect('painFlinch');}else if(wasCaught&&!state.event&&!state.ending){playVocal('breath',1);shortEffect('breathRelease');}};
const beforeDetailImpact=impact;
impact=function(part){beforeDetailImpact(part);if(part==='head'||part==='eyes')shortEffect('focusLoss');else if(part==='leg')shortEffect('legBuckling');else if(part==='arm')shortEffect('painFlinch');};
const beforeDetailToggle=toggleSound;
toggleSound=function(){beforeDetailToggle();if(!meta.preferences.sound){stopVocal();audioContext?.suspend?.();}};
const beforeDetailSettings=renderSettings;
renderSettings=function(){beforeDetailSettings();const box=document.createElement('div');box.classList.add('setting');const label=document.createElement('span');label.textContent='숨소리·비명';const button=document.createElement('button');button.textContent=meta.preferences.vocals===false?'꺼짐':'켜짐';button.onclick=()=>{meta.preferences.vocals=meta.preferences.vocals===false;if(!meta.preferences.vocals)stopVocal();save();renderSettings();};box.append(label,button);$('panelScroll').append(box);};
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopVocal();audioContext?.suspend?.();}else if(meta.preferences.sound)audioContext?.resume?.();});

// Choice presentation describes the engine's restriction; it never decides eligibility.
function choiceSurface(id,blocked='',grasp=false){if(grasp){const key=eventMonster(state.event)?.key;return key==='water'?'flood':key==='forest'?'roots':key==='market'?'cloth':state.event?'claw':'erosion';}if(!blocked)return 'open';if(/팔 부상|다리 부상|머리 부상|청각 부상|눈 부상/.test(blocked))return 'wound';if(/수위|밸브|펌프|배수/.test(blocked))return 'flood';if(/연결|단말기|화면/.test(blocked))return 'signal';if(/동료|동행|부축|같은 장소|먼저 만나/.test(blocked))return 'absence';if(/열쇠|물품/.test(blocked))return 'chain';return 'evidence';}
function choiceDecoration(kind){const svg=(body)=>'<svg viewBox="0 0 120 80" aria-hidden="true" focusable="false">'+body+'</svg>';if(kind==='chain')return svg('<g fill="none" stroke="currentColor" stroke-width="5" transform="rotate(-25 60 40)"><rect x="2" y="27" width="39" height="22" rx="11"/><rect x="35" y="27" width="39" height="22" rx="11"/><rect x="68" y="27" width="39" height="22" rx="11"/></g><rect x="47" y="28" width="29" height="32" rx="4" fill="#3e443f" stroke="currentColor"/><path d="M53 29v-9a9 9 0 0 1 18 0v9" fill="none" stroke="currentColor" stroke-width="4"/>');if(kind==='wound')return svg('<path d="M12 8L95 72M35 4L118 68" stroke="#c4b99f" stroke-width="14" opacity=".65"/><path d="M40 23l13 7-8 9 14 7-9 9" stroke="#a95961" fill="none" stroke-width="3"/>');if(kind==='absence')return svg('<path d="M30 68V31a20 20 0 0 1 40 0v37M19 68h65" fill="none" stroke="currentColor" stroke-width="3" stroke-dasharray="5 5"/><path d="M78 14l29 0-8 10m8-10-8-10" fill="none" stroke="currentColor" stroke-width="3"/>');if(kind==='signal')return svg('<path d="M15 40q45-48 90 0M28 51q32-34 64 0M42 62q18-18 36 0M20 8l80 64" fill="none" stroke="currentColor" stroke-width="3"/>');if(kind==='evidence')return svg('<path d="M26 8h48l18 18v47H26zM74 8v19h18M38 40h42M38 51h32M38 62h21" fill="none" stroke="currentColor" stroke-width="3"/>');return '';}
const plainChoiceButton=button;
button=function(id,label,blocked='',extra=''){const kind=choiceSurface(id,blocked);return plainChoiceButton(id,label,blocked,extra).replace('<button ','<button class="choiceCard surface-'+kind+'" data-surface="'+kind+'" ').replace('</button>',blocked?'<span class="choiceDecor" aria-hidden="true">'+choiceDecoration(kind)+'</span></button>':'</button>');};
graspChoice=function(id,label,blocked='',extra='',grasp=false){if(!grasp)return button(id,label,blocked,extra);const kind=choiceSurface(id,blocked,true);let html=plainChoiceButton(id,label,blocked,extra).replace('<button ','<button class="choiceCard graspedChoice surface-'+kind+'" data-surface="'+kind+'" ');const asset=kind==='roots'?'forest':kind==='cloth'?'market':kind==='flood'?'water':'hand';return html.replace('</button>','<span class="choiceIntruder" aria-hidden="true"><img class="choiceHand" src="assets/monsters/'+asset+'.png" alt=""><i class="choiceVeil"></i></span><span class="graspWhisper">'+(kind==='erosion'?'네 손은 누구의 것일까':kind==='flood'?'발 디딜 곳이 사라졌다':kind==='cloth'?'천이 길을 덮었다':kind==='roots'?'목소리 쪽은 막혔다':'손이 길을 빼앗았다')+'</span></button>');};
let choiceSnapshot=null;
function visibleChoiceSnapshot(){if(state.ending)return null;let list;if(state.event)list=eventChoices().map(o=>({id:'event:'+o.id,blocked:!!o.blocked,grasp:!!o.grasp}));else if(state.exit)list=epilogueChoices().filter(o=>!o.done).map(o=>({id:'epilogue:'+o.id,blocked:!!o.blocked}));else list=actions().map(a=>({id:a.id,blocked:!!reason(a),grasp:screenGripActive()&&state.screenGrip.action===a.id}));return {loc:state.loc,turn:state.turn,born:state.born,event:state.event?.type||'',stage:state.event?.stage||0,list};}
function choiceChanges(previous,current){if(!previous||!current||previous.loc!==current.loc||previous.born!==current.born||previous.turn===current.turn)return [];const old=new Map(previous.list.map(o=>[o.id,o]));return current.list.flatMap(o=>{const p=old.get(o.id);if(o.grasp&&(!p||!p.grasp))return [{id:o.id,kind:'taken'}];if(!o.blocked&&(!p||p.blocked))return [{id:o.id,kind:'revealed'}];return [];});}
const beforeChoiceRender=render;
render=function(){const next=visibleChoiceSnapshot(),changes=choiceChanges(choiceSnapshot,next);beforeChoiceRender();choiceSnapshot=next;if(!next||meta.preferences.reduce||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const buttons=$('actions')?.querySelectorAll('button')||[];for(const change of changes){const b=Array.from(buttons).find(b=>b.dataset.action===change.id);if(b)b.classList.add(change.kind==='taken'?'choiceTaken':'choiceRevealed');}if(changes.some(c=>c.kind==='taken'))soundFX('choiceTaken');else if(changes.some(c=>c.kind==='revealed'))soundFX('choiceReveal');};
const beforeChoiceSound=soundFX;
soundFX=function(type){if(type!=='choiceTaken'&&type!=='choiceReveal')return beforeChoiceSound(type);if(!meta.preferences.sound||document.hidden)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const t=audioContext.currentTime;if(type==='choiceTaken'){tone(85,t,.22,.025,'triangle');tone(54,t+.09,.3,.018,'sine');}else{tone(360,t,.1,.016);tone(480,t+.07,.18,.012);}}catch{}};
const beforeDecisionEnding=endingEvidence;
endingEvidence=function(){const decisions=Object.values(state.decisions||{});return beforeDecisionEnding()+(decisions.length?'<br>'+decisions.map(d=>'남긴 선택: '+escapeHTML(d.title)).join('<br>'):'');};
