function endingSceneSpec(id,context){const e=ENDING_SCENES[id];if(!e)return null;const c=context||{},party=c.party||[];let people=[];if(e.cast==='party')people=party;else if(e.cast==='operator'&&party.includes('윤서'))people=['윤서'];else if(e.cast==='sisters')people=['서진','해원'].filter(n=>party.includes(n));else if(e.cast==='mimic')people=c.fake||[];else if(e.cast==='changed')people=c.changed||[];else if(e.cast==='rejoined')people=c.rejoined||[];else if(e.cast==='attacker'&&c.attacker)people=[c.attacker];const portraits=people.slice(0,3).map(n=>({name:n,src:n===c.attacker?c.attackerPortrait:c.portraits?.[n]})).filter(p=>p.src);if(e.cast==='self')portraits.push({name:'나의 모습',src:c.player||'assets/player-aberrant.png'});return {...e,id,portraits,src:(e.monster||['assault','exhausted','signal','name'].includes(id))&&WORLD[c.loc]?'assets/'+WORLD[c.loc].art+(WORLD[c.loc].art==='lost-survivor'?'.png':'.jpg'):e.scene==='market'?'assets/market.jpg':'assets/endings/'+e.scene+'.png'};}
function endingArtwork(id,context,thumb=false){const e=endingSceneSpec(id,context);if(!e)return '';const title=ENDS.find(a=>a.id===id).title;return '<figure class="endingArtwork mood-'+e.mood+(thumb?' endingThumb':'')+'" role="img" aria-label="'+escapeHTML(title+' · '+e.caption)+'">'+endingImageTag(e,title)+'<div class="endingAtmosphere" aria-hidden="true"></div>'+(e.monster?'<div class="endingMonster" aria-hidden="true">'+imageTag('assets/monsters/'+e.monster+'.png','','')+'</div>':'')+'<div class="endingCast" aria-hidden="true">'+e.portraits.map(p=>imageTag(p.src,'','')).join('')+'</div>'+(e.object==='phone'?'<div class="endingPhone" aria-hidden="true"><i></i></div>':e.object==='mirror'?'<div class="endingBeam" aria-hidden="true"></div>':'')+(!thumb?'<figcaption>'+escapeHTML(e.caption)+'</figcaption>':'')+'</figure>';}
renderEnding=function(){const e=ENDS.find(e=>e.id===state.ending);if(!e)return;document.body.classList.add('endingScene');const context=endingContext();$('sceneView').innerHTML='<div class="sceneArt endingStage">'+endingArtwork(e.id,context)+'<div class="sceneTitle"><small>ENDING '+e.n+' / '+ENDS.length+'</small><h1>'+escapeHTML(e.title)+'</h1></div></div><div class="sceneBody"><h2 class="endingTitle">'+escapeHTML(e.title)+'</h2><p>'+escapeHTML(e.text)+'</p><div class="entry"><h3>이번 선택이 남긴 것</h3><p>'+endingEvidence()+'</p></div><details class="entry"><summary>다른 선택에서 확인할 것</summary><p>'+nextLead()+'</p></details><button id="restart" class="primary">다른 선택으로 다시 시작</button> <button id="endingBook">엔딩과 사건수첩</button></div>';$('restart').onclick=restart;$('endingBook').onclick=()=>{bookTab='endings';openView('book')};};
