const beforeChapterNarrative=sceneNarrative;
sceneNarrative=function(w,e){if(e||state.exit||state.loc!=='ward'||!OPENING_IDS.has(state.lastAction))return beforeChapterNarrative(w,e);const out=state.output||{text:'',lines:[]};let text=out.text||'';const notes=[text.indexOf('\n\n나래에게 지닌 물건'),text.indexOf('\n\n나래가 가방')].filter(i=>i>=0).sort((a,b)=>a-b)[0]??-1;if(notes>=0)text=text.slice(0,notes);const paras=t=>String(t).split(/\n\n/).filter(Boolean).map(p=>'<p>'+escapeHTML(p)+'</p>').join('');let html='<section class="novelChapter" aria-label="대피소에서 복도까지"><div class="prose">'+paras(text)+'</div>';for(const l of out.lines||[]){if(l.kind==='narration'){html+='<div class="prose beat">'+paras(l.text)+'</div>';continue;}if(l.kind==='thought'){html+='<p class="chapterThought">'+escapeHTML(l.text)+'</p>';continue;}html+=dialogueBubble(l);}if((out.lines||[]).some(l=>/ECHO/.test(l.who)))html+='<button id="readEchoReply" class="echoThreadLink">단말기에 남은 수신 자막 보기</button>';return html+'</section>';};
const chapterRenderMap=renderMap;renderMap=function(){chapterRenderMap();if(state.loc==='ward'&&(hasFlag('openingAwaitNara')||hasFlag('openingAwaitChoice'))){$('panelScroll').innerHTML='<div class="entry"><p>'+escapeHTML(objective())+'</p><p>계단으로 내려가기 전에 복도에서 대화를 마쳐야 합니다.</p></div>';}};
INTRO_PAGES.splice(0,INTRO_PAGES.length,['비가 그치지 않는 마을','이름을 잃은 채 낯선 방에서 눈을 뜹니다. 문밖의 발소리, 단말기 너머의 안내, 복도에서 마주칠 사람. 어디까지 믿을지는 아직 알 수 없습니다.'],['당신의 선택으로 이어지는 이야기','장면 아래에서 행동을 선택하세요. 길이 열리면 지도로 이동할 수 있습니다. 단말기에 남은 말은 ECHO, 발견한 물건과 기록은 소지품·수첩에서 다시 볼 수 있습니다. 자세한 조작법은 설정에서 확인할 수 있습니다.']);
