function identityRow(o){return '<section class="identityRow"><h4>'+escapeHTML({memory:'대화',object:'개인 소지품',trace:'몸과 움직임'}[o.mode])+'</h4><dl><dt>'+(o.mode==='trace'?'살피기 전 기억':'처음 기록')+'</dt><dd>'+emphasizeEvidence(o.first||'처음 본 내용이 남아 있지 않다.').replace(/\n/g,'<br>')+'</dd><dt>이번에 확인</dt><dd'+(o.noise?' class="observationStatic"':'')+'>'+emphasizeEvidence(o.current).replace(/\n/g,'<br>')+'</dd></dl><small>행동 '+o.turn+' 때 남긴 기록</small></section>';}
personEvidence=function(n){const c=state.npc[n],f=evidenceFile(n),obs=Object.values(c.observations||{}).filter(o=>o.version===1);let html='<div class="personReference"><h4>개인 소지품 · 첫 관찰</h4>'+(f.items.length?'<ul>'+f.items.map(i=>'<li><b>'+escapeHTML(i.name)+'</b><br>'+escapeHTML(i.detail)+'</li>').join('')+'</ul>':'<p>이전 저장에는 새 소지품 목록의 첫 관찰이 없습니다. 과거에 봤다고 덧붙이지 않습니다.</p>')+'<details><summary>처음 실제로 나눈 말</summary><p>'+escapeHTML(f.memory||'대화 기록 없음')+'</p><small>'+(f.loc?escapeHTML(WORLD[f.loc].name):'위치 미기록')+' · 행동 '+(f.turn??'?')+'</small></details>'+obs.map(identityRow).join('');if(obs.some(o=>o.band==='clouded'))html+='<p class="identityCaution">높은 침식 상태의 관찰이 포함돼 있습니다. 단말기를 끄거나 침식을 낮춘 뒤 같은 항목을 다시 확인할 수 있습니다.</p>';const history=(meta.npcHistory?.[n]||[]).filter(h=>h.cycle!==meta.cycle);if(history.length)html+='<details><summary>이전 회차와 별도 대조</summary>'+history.map(h=>'<p>'+h.cycle+'회차: '+escapeHTML(h.object).replace(/\n/g,'<br>')+'<br>이번 회차: '+escapeHTML(c.baseline?.object||'첫 관찰 없음').replace(/\n/g,'<br>')+'</p>').join('')+'<p>다른 회차의 물건 차이는 이번에 만난 인물의 정체를 판정하는 증거가 아닙니다.</p></details>';if(c.observationHistory?.length)html+='<details><summary>재확인하기 전의 관찰</summary>'+c.observationHistory.filter(o=>o.version===1).map(identityRow).join('')+'</details>';return html+'</div>';};
const identityNarrative=sceneNarrative;
sceneNarrative=function(w,e){let html=identityNarrative(w,e);const check=state.output?.identityCheck;if(check&&!state.exit&&!e)html+='<div class="identityCompare" aria-label="첫 기록과 현재 관찰 비교">'+identityRow(check)+'</div>';if(state.exit?.identityReports&&!state.ending)html+='<section class="identityCompare"><h3>구조 거점에서 함께 본 것</h3>'+Object.entries(state.exit.identityReports).map(([n,r])=>'<details open><summary>'+escapeHTML(n)+' · 가져온 기록과 지금 모습'+'</summary>'+r.rows.map(identityRow).join('')+'</details>').join('')+'</section>';return html;};
