// Screen infection is visual only: no random draws, lost text, or hidden controls.
function infectionLevel(){return state.ending||meta.preferences.reduce?0:state.erosion>=85?4:state.erosion>=65?3:state.erosion>=35?2:state.erosion>=15?1:0;}
const infectionRender=render;
render=function(){const result=infectionRender();document.body.dataset.infection=String(infectionLevel());$('infectionVeil').hidden=infectionLevel()===0;return result;};
const infectionEvidence=endingEvidence;
endingEvidence=function(){if(state.ending!=='outbreak')return infectionEvidence();const o=state.outbreak;return o?escapeHTML(o.source+'를 일반 대피소행 차량에 인계했다. '+o.warning+' 신호 노출자 확인 안내를 읽은 뒤에도 검사 생략에 서명했다. 그 차량이 도착한 대피소에서 첫 외부 감염이 보고됐다.'):'검사 절차를 생략한 일반 대피소 인계가 외부 감염의 시작이었다.';};
const infectionLead=nextLead;
nextLead=function(){return state.ending==='outbreak'?'높은 침식에서는 이상이 자연스럽게 보일 수 있다. 구조팀의 독립 대조를 받고, 이상이 있거나 확신할 수 없는 동료는 따로 확인하도록 맡길 수 있다. 격리·치료 요청은 일반 대피소행 인계와 다르다.':infectionLead();};
render();

function emphasizeEvidence(text){let count=0;return escapeHTML(text).replace(/스피커가 켜(?:졌을 때|질 때|진 동안)|방송이 끊긴 틈|소리가 끊기는 틈|고개를 돌릴 때|계속 보고 있으면|보고 있을 때|등을 보이지 말고|눈을 돌리고|목소리보다 바닥|이름을 불러|이름에 대답|발을 멈추고|낮은 발판|높은 계단|마른 발자국|발자국은 없다|물자국이 남지 않는다|그림자는 몸보다 늦게 움직인다|녹색|청색|붉은 불빛|흰 불빛|취소선|구조 완료|혜원|해원/g,part=>count++<6?'<strong class="clueEmphasis">'+part+'</strong>':part);}

function publicClaim(c){const text=String(c.text).replace(/\n판단:[^\n]*/g,'');if(c.kind==='대조')return {...c,kind:'남겨 둔 기록',title:'ECHO의 안내와 지닌 기록',text};if(c.kind==='구조팀 대조')return {...c,kind:'구조 거점의 관찰',text};if(String(c.kind).startsWith('관찰'))return {...c,kind:'관찰 기록',text};return {...c,text};}

// Opening and subsequent scenes share the same visible speech renderer.
function dialogueBubble(l,index=0){if(!l||typeof l.text!=='string'||!l.text.trim())return '';const player=l.who==='나';const speaker=player?'나':l.speaker||l.who||'상대';const portrait=!player&&PEOPLE[l.who]?imageTag(npcPortrait(l.who),speaker,'speakerPortrait'):'';return '<div class="dialogue sceneDialogue '+(player?'player':'other')+'" data-speaker="'+escapeHTML(speaker)+'" style="--speech-delay:'+Math.min(index*90,450)+'ms">'+portrait+'<div class="speechBody"><strong class="speakerName">'+escapeHTML(speaker)+'</strong><p class="speechText">'+distortSpeech(l.text,l.who)+'</p></div></div>';}
render();

// Keep image failures bounded: WebP -> original PNG -> legacy art -> text fallback.
function endingImageTag(spec,title){const sources=[...new Set([spec.src,...(spec.fallbacks||[])].filter(Boolean))];return '<img class="endingBackdrop" src="'+escapeHTML(sources[0])+'?v=520" alt="'+escapeHTML(title+'의 마지막 장면')+'" data-ending-sources="'+escapeHTML(JSON.stringify(sources))+'" data-ending-attempt="0" onerror="endingImageFailed(this)">';}
function endingImageFailed(img){let sources=[];try{sources=JSON.parse(img.dataset.endingSources||'[]');}catch{}const next=Number(img.dataset.endingAttempt||0)+1;img.dataset.endingAttempt=String(next);if(next<sources.length){img.src=sources[next]+'?v=520';return;}img.onerror=null;img.hidden=true;const figure=img.closest?.('.endingArtwork');if(figure&&!figure.querySelector('.endingImageNotice')){figure.classList.add('imageUnavailable');const notice=document.createElement('p');notice.className='endingImageNotice';notice.textContent='장면 이미지를 불러오지 못했습니다. 아래에서 결말을 계속 읽을 수 있습니다.';figure.append(notice);}}
// Refresh authored current dialogue after a content update without rerunning actions.
function refreshCurrentAuthoredScene(){if(state.contentRevision==='5.22')return;state.contentRevision='5.22';if(state.event||state.exit||state.ending||state.output?.identityCheck)return;const id=state.lastAction;if(!['firstMail','firstSave','nara','naraSymptoms',...Object.keys(CAST_SCENES).filter(k=>!['haewon','seojin','seojinTrail'].includes(k))].includes(id))return;let a=Object.values(ACTIONS).flat().find(a=>a.id===id);if(!a)return;if(id==='nara'){const reading=state.naraReading,cloth=state.naraCloth;a={...a,...naraEntrance()};state.naraReading=reading||state.naraReading;state.naraCloth=cloth||{owner:'나래',offered:true,used:false};}if(!a.dialogue)return;const introduced=new Set(state.met.filter(n=>id!=='nara'||n!=='나래'));const lines=a.dialogue.map(l=>{const kind=l.kind||'speech';let text=String(l.text||'');if(PEOPLE[l.who]){text=npcVoice(l.who,text);if(new RegExp(l.who+'(이라고|라고|이에요|예요|야|이고|입니다|[.])').test(text))introduced.add(l.who);}return {who:l.who,text:nameParticles(text),kind,speaker:PEOPLE[l.who]&&!introduced.has(l.who)?'복도에 있던 여자':l.who};});state.output={text:a.text||'',lines};state.transcript=state.transcript.filter(l=>!(l.action===id&&l.turn===state.turn&&l.loc===state.loc));state.transcript.push(...lines.map(l=>({...l,action:id,turn:state.turn,loc:state.loc})));state.transcript=state.transcript.slice(-150);if(id==='nara'){const memory=lines.filter(l=>l.who==='나래'&&/불빛|왼쪽 계단/.test(l.text)).map(l=>l.text).join(' / '),c=state.npc.나래;if(c.baseline)c.baseline.memory=memory;if(c.identityEvidence)c.identityEvidence.memory=memory;const h=meta.npcHistory?.나래?.find(h=>h.cycle===meta.cycle);if(h)h.memory=memory;}save();}
const contentAwareRender=render;
render=function(){refreshCurrentAuthoredScene();return contentAwareRender();};
function checkBundleVersion(){const files=['data.js','game.js','story.js','identity.js','infection.js','cast.js','ui.js'];const styleOk=!window.getComputedStyle||window.getComputedStyle(document.documentElement).getPropertyValue('--glassbay-build').trim()==='522';const ok=files.every(f=>window.GlassBayFiles?.[f]==='5.22')&&styleOk;window.GlassBayReady=ok;$('loadNotice').hidden=ok;if(!ok){$('loadMessage').textContent='일부 게임 파일이 이전 버전입니다.';$('loadDetail').textContent='업데이트의 코드 파일 전체를 같은 위치에 덮어쓴 뒤 새로고침해 주세요.';}return ok;}
render();showIntro();checkBundleVersion();

// All visual variation follows exposure and topic, never the answer's truth flag.
function immersiveEffectsAllowed(){return !meta.preferences.reduce&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches&&!state.ending;}
function terminalFxTier(){return immersiveEffectsAllowed()&&terminalOn()?infectionLevel():0;}
function terminalQuestionStyle(q,index=0){const tier=terminalFxTier();if(!tier)return 'quiet';const hash=Array.from(String(classify(q)||q)).reduce((n,c)=>n+c.charCodeAt(0),0);return (tier===1?['scan','quiet']:tier===2?['scan','echo','thread']:['scan','echo','thread','fractured'])[(hash+index)%(tier===1?2:tier===2?3:4)];}
function terminalQuestionButton(q,index=0){const effect=terminalQuestionStyle(q,index);return '<button class="terminalQuestion terminal-'+effect+'" data-question="'+escapeHTML(q)+'" data-fx="'+effect+'"><span class="questionGhost" aria-hidden="true">'+escapeHTML(q)+'</span><span class="questionLabel">'+escapeHTML(q)+'</span><span class="questionSignal" aria-hidden="true"><i></i><i></i><i></i></span></button>';}
function terminalFxFrame(){const last=state.chat.at(-1),key=[state.born,state.chat.length,last?.turn,last?.q,last?.a].join('|');const fresh=terminalFxCursor!==null&&terminalFxCursor!==key&&!!last;terminalFxCursor=key;return {fresh:!!fresh&&immersiveEffectsAllowed(),tier:terminalFxTier()};}
function terminalAtmosphere(frame){if(!immersiveEffectsAllowed())return '';const tier=frame.tier;return '<div class="terminalAtmosphere '+(frame.fresh?'signalArrived':'')+'" aria-hidden="true"><div class="signalTrace"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>'+(tier>=3?'<span class="connectionPull">'+(tier===4?'끊지 마. 한 번만 더.':'다시 확인하고 싶다.')+'</span>':'')+'</div>';}
function terminalMessageHTML(m,fresh=false){return '<article class="message'+(fresh?' receptionFx':'')+'"><div class="q">'+escapeHTML(m.q)+'</div><div class="a"><span class="replyGhost" aria-hidden="true">'+escapeHTML(m.a)+'</span><span class="replyOriginal">'+emphasizeEvidence(m.a)+'</span>'+(m.erosionCost?'<small class="paidCost">침식 +'+m.erosionCost+'</small>':'')+'</div>'+comparisonCard(m)+'</article>';}
function updateErosionAtmosphere(){const allowed=immersiveEffectsAllowed(),tier=allowed?infectionLevel():0;const previous=erosionFxSnapshot;const token=String(state.born??'')+'|'+String(meta.cycle);erosionFxSnapshot={token,tier,turn:state.turn};document.body.dataset.erosionFx=String(tier);document.body.dataset.terminalPull=String(allowed&&terminalOn()&&state.erosion>=65?Math.min(2,tier-2):0);document.body.dataset.signalLive=terminalOn()?'on':'off';if($('erosionFx'))$('erosionFx').hidden=tier===0;const rising=!!previous&&previous.token===token&&tier>previous.tier&&state.turn!==previous.turn;const falling=!!previous&&previous.token===token&&tier<previous.tier&&state.turn!==previous.turn;if(!allowed||!previous||previous.token!==token||state.turn!==previous.turn)document.body.classList.remove('erosionSurge','erosionRelief');if(allowed&&(rising||falling)){void document.body.offsetWidth;document.body.classList.add(rising?'erosionSurge':'erosionRelief');}if(!allowed){$('fracture').hidden=true;$('infectionVeil').hidden=true;}}
const immersiveRender=render;
render=function(){const result=immersiveRender();updateErosionAtmosphere();return result;};
const immersiveOpenView=openView;
openView=function(view,sub){const result=immersiveOpenView(view,sub);updateErosionAtmosphere();return result;};
